SELECT s.operator FROM (
  SELECT service_no, operator, SUM(route_km) AS total_km FROM services JOIN route_stops ON services.service_no = route_stops.service_no WHERE category = 'TRUNK' GROUP BY service_no, operator ORDER BY total_km DESC LIMIT 10
) AS s

SELECT T2.hour FROM (
  SELECT stop_code, SUM(T1.am_peak_trips) AS total_trips FROM od_stop_flows AS T1 JOIN stops AS T2 ON T1.origin_stop = T2.stop_code GROUP BY T2.stop_code
) AS T3 JOIN (
  SELECT stop_code, hour FROM route_stops WHERE direction = 1 AND stop_sequence = 1
) AS T4 ON T3.stop_code = T4.stop_code WHERE T3.stop_code = '83139' ORDER BY T3.total_trips DESC LIMIT 1

